-- Production migration applied 2026-09-16. Historical 12-month bootstrap only; incremental Radar remains the ongoing path.
insert into public.client_opportunity_matches(client_id,opportunity_id,capability_id,match_status,deterministic_score,deterministic_reasons,participation_allowed,method_version)
select e.client_id,o.id,e.capability_id,'queued_for_analysis',least(100,60+10*count(distinct t.term)),jsonb_build_array(jsonb_build_object('include_matches',jsonb_agg(distinct t.term),'rule','capability_term_match_backfill','prompt','Prompt Radar UNI v1.0')),false,'Prompt Radar UNI v1.0'
from public.client_radar_enrollments e join public.client_capability_match_terms t on t.client_id=e.client_id and t.capability_id=e.capability_id and t.active and t.term_kind='include' join public.public_opportunities o on lower(coalesce(o.title,'')||' '||coalesce(o.object_text,'')) like '%'||lower(t.term)||'%'
where e.monitoring_enabled=true and o.publication_date>=current_date-interval '12 months' and not exists(select 1 from public.client_capability_match_terms x where x.client_id=e.client_id and x.capability_id=e.capability_id and x.active and x.term_kind='exclude' and lower(coalesce(o.title,'')||' '||coalesce(o.object_text,'')) like '%'||lower(x.term)||'%')
group by e.client_id,o.id,e.capability_id,e.participation_enabled
on conflict(client_id,opportunity_id,capability_id) do update set match_status=excluded.match_status,deterministic_score=excluded.deterministic_score,deterministic_reasons=excluded.deterministic_reasons,participation_allowed=false,method_version=excluded.method_version,updated_at=now();
update public.client_radar_enrollments set initial_load_status='completed',initial_load_started_at=coalesce(initial_load_started_at,now()),initial_load_completed_at=now(),last_sync_at=now(),updated_at=now() where monitoring_enabled=true;